import { test, expect } from '@playwright/test';

test.describe('Table Column Sort Direction Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should display sort direction arrow icon when column is sorted', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Click on column header to sort
    const nameHeader = page.getByRole('columnheader', { name: 'Name' });
    await nameHeader.click();

    // Verify sort direction arrow appears
    const sortArrow = page.getByRole('img', { name: /sort direction/i });
    await expect(sortArrow).toBeVisible();

    // Verify arrow points up (ascending)
    const arrowIcon = page.locator('[data-testid="sort-arrow"]');
    await expect(arrowIcon).toHaveAttribute('data-direction', 'asc');

    // Verify sort indicator text is visible
    const sortIndicator = page.getByText('Name');
    await expect(sortIndicator).toBeVisible();

    // Verify table rows are sorted by name
    const rows = page.locator('[data-testid="table-row"]');
    const rowNames = await rows.allTextContents();
    expect(rowNames[0]).toContain('Alice');
    expect(rowNames[rows.count() - 1]).toContain('Zoe');
  });

  test('should update sort direction arrow when column is re-sorted', async ({ page }) => {
    // Click on column header to sort ascending
    const emailHeader = page.getByRole('columnheader', { name: 'Email' });
    await emailHeader.click();

    // Verify ascending arrow is displayed
    const sortArrow = page.getByRole('img', { name: /sort direction/i });
    await expect(sortArrow).toBeVisible();
    const arrowIcon = page.locator('[data-testid="sort-arrow"]');
    await expect(arrowIcon).toHaveAttribute('data-direction', 'asc');

    // Click on the same column header to sort descending
    await emailHeader.click();

    // Verify sort direction arrow updates to descending
    await expect(arrowIcon).toHaveAttribute('data-direction', 'desc');

    // Verify sort indicator text is updated
    const sortIndicator = page.getByText('Email');
    await expect(sortIndicator).toBeVisible();

    // Verify table rows are sorted in descending order
    const rows = page.locator('[data-testid="table-row"]');
    const rowEmails = await rows.allTextContents();
    expect(rowEmails[0]).toContain('zoe@example.com');
    expect(rowEmails[rows.count() - 1]).toContain('alice@example.com');
  });
});
